+it("wraps each sender's original content without exposing profile metadata", () => {
+  const author = {
+    evidence: "provider-verified" as const,
+    identity: { kind: "person" as const, key: "person:cole", issuer: "test", subject: "cole" },
+    presentation: { displayName: "Cole", handle: "cole@phosphor.co", avatarUrl: "https://example.test/avatar" },
+  };
+  const second = [{ type: "text" as const, text: "Second message", mentions: [] }];
+  const result = withP6rNativeAuthorContext(
+    [...input, ...second], [author, null], undefined, [input, second],
+  );
+  expect(result.inputGroups).toEqual([
+    [
+      { type: "text", visibility: "agent-only", mentions: [], text: "[from=cole@phosphor.co]\n" },
+      ...input,
+      { type: "text", visibility: "agent-only", mentions: [], text: "\n[/from=cole@phosphor.co]" },
+    ],
+    second,
+  ]);
+  expect(result.inputGroups?.[0]?.[1]).toBe(input[0]);
+});
